using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateAuthoredForestRoute
{
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();var car=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var rb=car.GetComponent<Rigidbody>();var pos=rb.position;var rotation=rb.rotation;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused,auto=car.automaticSimulation,external=car.externalControl;float maxGap=0,maxHeight=0;int tested=0;string result="";
 try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;car.externalControl=true;car.automaticSimulation=false;route.Prepare();
 foreach(int arm in new[]{0,1}){
 route.LoadWindow(arm,0);Physics.SyncTransforms();for(int i=0;i<5;i++){var r=route.arms[arm].records[i];var d=route.arms[arm].descriptions[r.module];maxGap=Mathf.Max(maxGap,Vector3.Distance(route.RoutePoint(arm,i,d.length),route.RoutePoint(arm,i+1,0)));for(float s=0;s<d.length;s+=2){var p=route.RoutePoint(arm,i,s);foreach(float side in new[]{-1.2f,0,1.2f}){Vector3 tangent=(route.RoutePoint(arm,i,Mathf.Min(d.length,s+1))-route.RoutePoint(arm,i,Mathf.Max(0,s-1))).normalized;var point=p+Vector3.Cross(Vector3.up,tangent).normalized*side;var hits=Physics.RaycastAll(point+Vector3.up*15,Vector3.down,40,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.GetComponent<ForestGroundPatch>()!=null).OrderBy(h=>h.distance).ToArray();if(hits.Length==0)throw new Exception("No road contact arm="+arm+" block="+i+" s="+s);float error=Mathf.Abs(hits[0].point.y-p.y);maxHeight=Mathf.Max(maxHeight,error);if(error>1)throw new Exception("Road covered/mismatched arm="+arm+" block="+i+" s="+s+" error="+error+" collider="+hits[0].collider.name);tested++;}}}
 var start=route.RoutePoint(arm,0,4);rb.position=start+Vector3.up*.55f;rb.rotation=Quaternion.LookRotation(route.RoutePoint(arm,0,8)-start);car.transform.SetPositionAndRotation(rb.position,rb.rotation);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;car.ResetState();car.SetTransmission(false,false);car.SetInput(new VehicleControlInput{brake=1});Physics.SyncTransforms();for(int i=0;i<150;i++)Step(car);double progress=4;
 for(int i=0;i<16000;i++){float best=float.MaxValue;double nearest=progress;int block=Math.Min(4,(int)(progress/46.3));for(int b=Math.Max(0,block-1);b<=Math.Min(5,block+1);b++){var r=route.arms[arm].records[b];var d=route.arms[arm].descriptions[r.module];for(float s=0;s<d.length;s+=.8f){float dist=(route.RoutePoint(arm,b,s)-rb.position).sqrMagnitude;if(dist<best){best=dist;nearest=r.distance+s;}}}progress=nearest;int n=0;while(n<5&&route.arms[arm].records[n+1].distance<progress)n++;var record=route.arms[arm].records[n];float local=(float)(progress-record.distance);var descriptor=route.arms[arm].descriptions[record.module];Vector3 target=local+8<descriptor.length?route.RoutePoint(arm,n,local+8):route.RoutePoint(arm,n+1,local+8-descriptor.length);var goal=car.transform.InverseTransformPoint(target);car.SetInput(new VehicleControlInput{throttle=car.SpeedKmh<15?1f:0,steering=Mathf.Clamp(Mathf.Atan2(goal.x,Mathf.Max(1,goal.z))*Mathf.Rad2Deg/24,-1,1)});Step(car);if(rb.position.y<route.RoutePoint(arm,n,Mathf.Clamp(local,0,descriptor.length)).y-2)throw new Exception("Below authored road arm="+arm+" progress="+progress);if(progress>150)break;}
 if(progress<150)throw new Exception("Authored road drive blocked arm="+arm+" at="+progress+" p="+rb.position+" speed="+car.SpeedKmh+" rpms="+car.EngineRpm+" road="+route.RoutePoint(arm,0,(float)progress)+" hits="+string.Join(";",car.Wheels.Select(w=>{WheelHit h;return w.GetGroundHit(out h)?h.collider.name+" parent="+h.collider.transform.parent.name+" p="+h.point+" rpm="+w.rpm+" T="+w.motorTorque:"AIR";}))+" nearby="+string.Join(";",Physics.OverlapBox(rb.position+car.transform.forward,new Vector3(1.1f,1,2.5f),car.transform.rotation,~0,QueryTriggerInteraction.Ignore).Where(c=>c.attachedRigidbody!=rb).Select(c=>c.name+" parent="+c.transform.parent.name)));result+="direction "+arm+" driven="+progress.ToString("F1")+"m; ";
 }
 foreach(int arm in new[]{0,1}){var records=route.arms[arm].records;int far=Array.FindIndex(records,r=>r.distance>=9999000);if(far<0)throw new Exception("Route too short");Vector3 delta=route.Position(arm,far);delta=new Vector3(Mathf.Round(delta.x/100)*100,0,Mathf.Round(delta.z/100)*100);rb.linearVelocity=new Vector3(2,0,3);var velocity=rb.linearVelocity;route.ShiftOrigin(delta);if((rb.linearVelocity-velocity).magnitude>.01f)throw new Exception("Origin shift changed momentum");route.LoadWindow(arm,far);Physics.SyncTransforms();var p=route.RoutePoint(arm,far,10);var hits=Physics.RaycastAll(p+Vector3.up*15,Vector3.down,40,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.GetComponent<ForestGroundPatch>()!=null).ToArray();if(hits.Length==0)throw new Exception("Far road absent");if(route.LoadedBlocks>route.ahead+route.behind+8)throw new Exception("Streaming unbounded");result+="direction "+arm+" far road="+(records[far].distance/1000).ToString("F2")+"km; ";}
 return "PASS authored-model streaming: "+tested+" road/wheel-path samples, seam="+maxGap.ToString("F5")+"m, max road-height error="+maxHeight.ToString("F2")+"m; "+result+"loaded="+route.LoadedBlocks;
 }finally{route.ShiftOrigin(new Vector3(-(float)route.OriginX,0,-(float)route.OriginZ));rb.position=pos;rb.rotation=rotation;car.transform.SetPositionAndRotation(pos,rotation);rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;car.SetInput(default);car.ResetState();car.automaticSimulation=auto;car.externalControl=external;Physics.simulationMode=mode;EditorApplication.isPaused=paused;}
 }
 static void Step(VehiclePhysics physics){physics.Simulate(Time.fixedDeltaTime);Physics.Simulate(Time.fixedDeltaTime);physics.SendMessage("LateUpdate");}
}


